def upload_from_url(url, profile=None, label=None):
    """
    Saves image from url with TMP prefix and returns img_id.
    """
    if profile is None:
        profile = get_default_profile()
    if label is None:
        label = url
    data = {'url': url, 'label': label, 'profile': profile}
    r = requests.post(
        '%s/image/upload_from_url' % get_api_url(), data=data)
    r.raise_for_status()
    return r.json()['img_id']


